function ___(uri) {
    var lang = ElStatsView.app_language;

    // Absolute link
    if(uri.indexOf('//') > -1 && uri.indexOf('//') < 8) {
        var arr = uri.split('//');
        arr[1] = lang+'/'+arr[1];
        uri = arr.join('//');

    }
    // Relative link
    else {
        uri = '/'+lang+'/'+uri;
    }

    uri = uri.replace(lang+'//', lang+'/');

    // Fix cases of this function being run twice on this uri
    uri = uri.replace('/'+lang+'/'+lang+'/', '/'+lang+'/');

    return uri;
}
