           function historyListPush(h,url,limit) {
               if(!h || typeof h == "undefined") {
                   h = {0: location.href};	
               } 

               var length = $.jsonLength(h);  

               if(location.href != h[length-1]) {
                   h[length] = url;

                   // Limit of [var limit] items
                   if(length >= limit) {
                       var h_new = {};
                       $.each(h, function(k,v) {
                           if(k == 0) { return true; } // continue
                           h_new[k-1] = v;
                       });
                       h = h_new;
                   }
               }	
               return h;

           } // END function

