                $.each($(sel).find('img'), function(k,v) {
                    $(v).attr('alt', $(v).attr('alt').replace(' button', '') );

                });
            }

            $(sel).keypress(function(e) {
                if (e.which == 13) {

                    $(this).click();
                }
            });

            if(shouldFocusOnDetect) {
                $(sel).first().focus();
            }

            clearInterval(stBtnTabbable);
        }
    }, ms);
}


